// Only the explicitly verified runtime images above are redirected.
const deliveryBySource = new Map(IMAGE_DELIVERY.map(entry => [entry.source, entry.optimized]));
export const IMAGE_DELIVERY_FILES = Object.freeze(IMAGE_DELIVERY.map(entry => entry.optimized));

export function imageURL(relativePath, baseURL = import.meta.url) {
  const original = new URL(relativePath, baseURL);
  const assetBase = new URL('../assets/', baseURL);
  if (original.origin !== assetBase.origin || !original.pathname.startsWith(assetBase.pathname)) return original;
  const source = 'assets/' + original.pathname.slice(assetBase.pathname.length);
  const optimized = deliveryBySource.get(source);
  if (!optimized) return original;
  const result = new URL('../' + optimized, baseURL);
  result.search = original.search;
  result.hash = original.hash;
  return result;
}
